#include <iostream>
#include <stdexcept>
#include <string>

int safe_div(int a, int b) {
    if (b == 0) throw std::runtime_error("division by zero");
    return a / b;
}

int main() {
    try {
        safe_div(1, 0);
    } catch (const std::exception& e) {
        std::cout << e.what() << '\n';
    }
}
